/*!
 * Themeasy — Business Hours
 *
 * Drives the .tms-business-hours widget's live state:
 *   - Recomputes the "today" row highlight and the Open/Closed badge on the
 *     SITE clock (data-utc-offset minutes), healing page-cache staleness
 *   - Re-checks on every minute boundary so the badge flips at the exact
 *     opening/closing minute, plus instantly on tab refocus
 *   - Overnight ranges (e.g. 22:00 – 02:00) include yesterday's spill
 *   - No vendor dependencies; pure class/text toggles (no motion). The editor
 *     preview (--static) and no-JS visitors keep the server-rendered state.
 *
 * Namespace:    window.Themeasy.businessHours
 * Pattern:      IIFE + onDomReady() + boot()
 * Idempotent:   each element tears down its prior timer before rebinding.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.businessHours = window.Themeasy.businessHours || {}

  // ------------------------------------------------------------------------
  // Selectors & constants
  // ------------------------------------------------------------------------
  const SELECTOR_WIDGET = '.tms-business-hours'
  const SELECTOR_ROW = '.tms-business-hours__row'
  const SELECTOR_BADGE = '.tms-business-hours__badge'
  const SELECTOR_BADGE_LABEL = '.tms-business-hours__badge-label'

  const CLASS_STATIC = 'tms-business-hours--static' // editor preview = inert
  const CLASS_TODAY = 'tms-business-hours__row--today'
  const CLASS_OPEN = 'tms-business-hours__badge--open'
  const CLASS_CLOSED = 'tms-business-hours__badge--closed'

  const MS_MINUTE = 60 * 1000

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  /**
   * Parse the PHP-precomputed ranges attribute ("540-1080,1320-120") into
   * [start, end] minute pairs. PHP owns the free-text parsing; this side only
   * consumes structured data.
   *
   * @param {string} raw Attribute value.
   * @returns {Array<Array<number>>} Minute pairs.
   */
  function parseRanges(raw) {
    if (!raw) return []

    const ranges = []
    const parts = raw.split(',')

    for (let i = 0; i < parts.length; i++) {
      const pair = parts[i].split('-')
      if (pair.length !== 2) continue

      const start = parseInt(pair[0], 10)
      const end = parseInt(pair[1], 10)
      if (isNaN(start) || isNaN(end)) continue

      // PHP never emits zero-length ranges; keep the guard for parity.
      if (start === end) continue

      ranges.push([start, end])
    }

    return ranges
  }

  /**
   * Current moment on the SITE clock, derived from the UTC offset PHP stamped
   * at render time. Reading the UTC components of a shifted Date is the
   * classic trick to get wall-clock parts in an arbitrary fixed offset.
   *
   * @param {number} offsetMinutes Site UTC offset in minutes.
   * @returns {{day: number, minutes: number}} ISO weekday (1 = Monday) + minutes since midnight.
   */
  function siteNow(offsetMinutes) {
    const shifted = new Date(Date.now() + (offsetMinutes * MS_MINUTE))

    return {
      day: ((shifted.getUTCDay() + 6) % 7) + 1,
      minutes: (shifted.getUTCHours() * 60) + shifted.getUTCMinutes()
    }
  }

  // ------------------------------------------------------------------------
  // State application
  // ------------------------------------------------------------------------

  /**
   * Recompute and apply the widget's live state: today row classes plus the
   * Open/Closed badge (class, label text, hidden state). Mirrors the PHP
   * compute_status() logic exactly.
   *
   * @param {HTMLElement} rootEl Widget root.
   */
  function applyState(rootEl) {
    const offset = parseInt(rootEl.getAttribute('data-utc-offset'), 10)
    if (isNaN(offset)) return

    const now = siteNow(offset)
    const today = String(now.day)
    const yesterday = String(now.day === 1 ? 7 : now.day - 1)

    let isOpen = false
    let anyToday = false
    let hasUnknown = false

    const rows = rootEl.querySelectorAll(SELECTOR_ROW)

    rows.forEach(function (row) {
      const daysRaw = row.getAttribute('data-days') || ''
      const days = daysRaw ? daysRaw.split(',') : []
      const coversToday = days.indexOf(today) !== -1

      row.classList.toggle(CLASS_TODAY, coversToday)

      const closed = row.getAttribute('data-closed') === 'true'
      const ranges = closed ? [] : parseRanges(row.getAttribute('data-ranges') || '')

      if (coversToday) {
        anyToday = true

        if (!closed && row.getAttribute('data-indeterminate') === 'true') {
          hasUnknown = true
        }

        ranges.forEach(function (range) {
          const start = range[0]
          const end = range[1]

          // An end below its start wraps past midnight: open from start on.
          if (end > start ? (now.minutes >= start && now.minutes < end) : (now.minutes >= start)) {
            isOpen = true
          }
        })
      }

      // Overnight spill: yesterday's "22:00 – 02:00" keeps early hours open.
      if (days.indexOf(yesterday) !== -1) {
        ranges.forEach(function (range) {
          if (range[1] <= range[0] && now.minutes < range[1]) {
            isOpen = true
          }
        })
      }
    })

    // ------------------------------------------------------------------------
    // Badge.
    // ------------------------------------------------------------------------
    const badge = rootEl.querySelector(SELECTOR_BADGE)
    if (!badge) return

    const status = isOpen ? 'open' : (anyToday && hasUnknown ? 'unknown' : 'closed')

    // Unknown = today's hours exist but carry no parseable times; hide rather
    // than guess (PHP renders the same way).
    if (status === 'unknown') {
      badge.classList.remove(CLASS_OPEN, CLASS_CLOSED)
      badge.setAttribute('hidden', 'hidden')
      return
    }

    badge.removeAttribute('hidden')
    badge.classList.toggle(CLASS_OPEN, status === 'open')
    badge.classList.toggle(CLASS_CLOSED, status !== 'open')

    const label = badge.querySelector(SELECTOR_BADGE_LABEL)
    if (!label) return

    const text = status === 'open'
      ? badge.getAttribute('data-open-text')
      : badge.getAttribute('data-closed-text')

    if (text && label.textContent !== text) {
      label.textContent = text
    }
  }

  // ------------------------------------------------------------------------
  // Scheduling
  // ------------------------------------------------------------------------

  /**
   * Schedule the next re-check just past the next minute boundary, so the
   * badge flips at the exact opening/closing minute.
   *
   * @param {Function} fn Tick callback.
   * @returns {number} Timeout id.
   */
  function scheduleNextMinute(fn) {
    const delay = MS_MINUTE - (Date.now() % MS_MINUTE) + 250
    return window.setTimeout(fn, delay)
  }

  /**
   * Stop the re-sync loop attached to a widget root (idempotent).
   *
   * @param {HTMLElement} rootEl Widget root.
   */
  function stopInstance(rootEl) {
    const instance = rootEl._tmsBusinessHoursInstance
    if (!instance) return

    if (instance.timeout) {
      window.clearTimeout(instance.timeout)
      instance.timeout = null
    }

    if (instance.onVisibility) {
      document.removeEventListener('visibilitychange', instance.onVisibility)
      instance.onVisibility = null
    }

    delete rootEl._tmsBusinessHoursInstance
  }

  /**
   * Bind a single widget instance.
   *
   * @param {HTMLElement} rootEl Widget root.
   */
  function bindInstance(rootEl) {
    // Elementor re-renders widgets in the editor; always tear down first.
    stopInstance(rootEl)

    // Editor preview: the content_template computes a static preview state.
    if (rootEl.classList.contains(CLASS_STATIC)) return

    const instance = {
      timeout: null,
      onVisibility: null
    }

    rootEl._tmsBusinessHoursInstance = instance

    function tick() {
      applyState(rootEl)
      instance.timeout = scheduleNextMinute(tick)
    }

    // Timers throttle in background tabs; refocus re-syncs instantly.
    instance.onVisibility = function () {
      if (document.visibilityState === 'visible') {
        applyState(rootEl)
      }
    }

    document.addEventListener('visibilitychange', instance.onVisibility)

    // First paint now (heals page-cache staleness); ticks align to minutes.
    tick()
  }

  // ------------------------------------------------------------------------
  // Core init
  // ------------------------------------------------------------------------

  /**
   * Initialize business-hours widgets within the given scope.
   *
   * @param {ParentNode} [root=document] Scope to query inside.
   */
  window.Themeasy.businessHours.init = function (root) {
    const scope = root || document
    const widgets = scope.querySelectorAll(SELECTOR_WIDGET)
    if (!widgets.length) return

    widgets.forEach(bindInstance)
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.businessHours.init()
    }
  }

  window.Themeasy.businessHours.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(boot)
})(window, document)
